css:
@page {
    size: A4;
    margin: 10mm 12mm;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body,
.print-format {
    font-size: 11px;
    line-height: 1.4;
    color: #1a1a1a;
    background: #fff;
    font-family: Arial, Helvetica, sans-serif;
}

.po-container {
    width: 100%;
    padding: 0;
}

/* ── Header ── */
.po-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    border-bottom: 3px solid #333;
    padding-bottom: 10px;
    margin-bottom: 10px;
}

.company-info {
    flex: 1;
}

.company-logo {
    max-height: 60px;
    max-width: 120px;
    margin-bottom: 6px;
}

.company-name {
    font-size: 18px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #222;
    margin-bottom: 2px;
}

.company-detail {
    font-size: 9px;
    color: #555;
    line-height: 1.5;
}

.po-title-block {
    text-align: right;
}

.po-title {
    font-size: 22px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 2px;
    color: #333;
}

.po-number {
    font-size: 13px;
    font-weight: 700;
    margin-top: 4px;
    color: #444;
}

/* ── Meta Grid ── */
.po-meta-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 0;
    margin-bottom: 12px;
    border: 1px solid #ccc;
}

.meta-cell {
    width: 33.333%;
    padding: 6px 10px;
    border-bottom: 1px solid #eee;
    border-right: 1px solid #eee;
}

.meta-cell:nth-child(3n) {
    border-right: none;
}

.meta-cell .label {
    font-size: 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #888;
    font-weight: 600;
    margin-bottom: 1px;
}

.meta-cell .value {
    font-size: 11px;
    font-weight: 700;
    color: #222;
}

/* ── Items Table ── */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
    font-size: 10px;
}

.items-table thead th {
    background: #444;
    color: #fff;
    font-size: 8px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 5px 4px;
    text-align: center;
    border: 1px solid #333;
}

.items-table thead th.text-left {
    text-align: left;
}

.items-table thead th.text-right {
    text-align: right;
}

.items-table tbody td {
    padding: 4px 4px;
    border: 1px solid #ddd;
    vertical-align: middle;
}

.items-table tbody tr:nth-child(even) {
    background: #f9f9f9;
}

.items-table tbody tr:hover {
    background: #f0f4ff;
}

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.text-left {
    text-align: left;
}

.fw-bold {
    font-weight: 700;
}

/* ── Totals ── */
.totals-block {
    display: flex;
    justify-content: flex-end;
    margin-top: 8px;
}

.totals-table {
    width: 280px;
    border-collapse: collapse;
}

.totals-table td {
    padding: 4px 8px;
    font-size: 11px;
    border-bottom: 1px solid #eee;
}

.totals-table td:first-child {
    color: #555;
    text-align: left;
}

.totals-table td:last-child {
    text-align: right;
    font-weight: 700;
}

.totals-table .grand-total td {
    font-size: 14px;
    font-weight: 900;
    border-top: 2px solid #333;
    border-bottom: 2px solid #333;
    padding: 6px 8px;
    color: #222;
}

/* ── Remarks ── */
.remarks-section {
    margin-top: 12px;
    padding: 8px;
    border: 1px solid #ddd;
    background: #fafafa;
    font-size: 10px;
}

.remarks-section .label {
    font-weight: 700;
    font-size: 9px;
    text-transform: uppercase;
    color: #666;
    margin-bottom: 4px;
}

/* ── Footer ── */
.po-footer {
    margin-top: 20px;
    display: flex;
    justify-content: space-between;
    border-top: 1px solid #ccc;
    padding-top: 15px;
}

.signature-block {
    width: 200px;
    text-align: center;
}

.signature-line {
    border-top: 1px solid #333;
    margin-top: 40px;
    padding-top: 4px;
    font-size: 9px;
    color: #666;
}

.po-print-footer {
    text-align: center;
    font-size: 8px;
    color: #bbb;
    margin-top: 15px;
}

@media print {
    .page-break {
        display: none;
    }
}

html:
{% set company_doc = frappe.get_doc("Company", doc.company) %}
{% set company_name = company_doc.company_name or doc.company %}
{% set company_phone = company_doc.phone_no or "" %}
{% set company_email = company_doc.email or "" %}
{% set company_website = company_doc.website or "" %}
{% set company_address = "" %}
{% if company_doc.get("company_address") %}
{% set addr = frappe.get_doc("Address", company_doc.company_address) %}
{% set company_address = [addr.address_line1 or "", addr.address_line2 or "", addr.city or "", addr.state or "", addr.pincode or ""] | select | join(", ") %}
{% endif %}
{% set company_tax_id = company_doc.tax_id or "" %}
{% set currency = doc.currency or frappe.db.get_value("Company", doc.company, "default_currency") or "USD" %}
{% set supplier_doc = frappe.get_doc("Supplier", doc.supplier) if doc.supplier else None %}

{# Print settings from custom fields #}
{% set show_stock = doc.get("custom_print_show_stock") %}
{% set show_transit = doc.get("custom_print_show_transit") %}
{% set show_packing = doc.get("custom_print_show_packing") %}
{% set show_discount = doc.get("custom_print_show_discount") %}
{% set show_category = doc.get("custom_print_show_category") %}
{% set show_generic = doc.get("custom_print_show_generic") %}

{# Count visible columns for colspan #}
{% set extra_cols = [] %}
{% if show_stock %}{% set _ = extra_cols.append(1) %}{% endif %}
{% if show_transit %}{% set _ = extra_cols.append(1) %}{% endif %}
{% if show_packing %}{% set _ = extra_cols.append(1) %}{% set _ = extra_cols.append(1) %}{% set _ = extra_cols.append(1) %}{% endif %}
{% if show_discount %}{% set _ = extra_cols.append(1) %}{% endif %}
{% if show_generic %}{% set _ = extra_cols.append(1) %}{% endif %}
{% if show_category %}{% set _ = extra_cols.append(1) %}{% set _ = extra_cols.append(1) %}{% endif %}

<div class="po-container">
    <!-- Header -->
    <div class="po-header">
        <div class="company-info">
            {% if company_doc.get("company_logo") %}
            <img class="company-logo" src="{{ company_doc.company_logo }}" alt="{{ company_name }}" />
            {% endif %}
            <div class="company-name">{{ company_name }}</div>
            <div class="company-detail">
                {% if company_address %}{{ company_address }}<br>{% endif %}
                {% if company_phone %}Tel: {{ company_phone }}{% endif %}
                {% if company_phone and company_email %} &bull; {% endif %}
                {% if company_email %}{{ company_email }}{% endif %}
                {% if company_website %}<br>{{ company_website }}{% endif %}
                {% if company_tax_id %}<br>Tax ID: {{ company_tax_id }}{% endif %}
            </div>
        </div>
        <div class="po-title-block">
            <div class="po-title">Purchase Order</div>
            <div class="po-number">{{ doc.name }}</div>
        </div>
    </div>

    <!-- Meta Grid -->
    <div class="po-meta-grid">
        <div class="meta-cell">
            <div class="label">Supplier</div>
            <div class="value">{{ doc.supplier_name or doc.supplier }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">Date</div>
            <div class="value">{{ frappe.utils.formatdate(doc.transaction_date, "dd-MM-yyyy") }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">Alias Name</div>
            <div class="value">{{ doc.get("custom_alias_name") or "-" }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">P/O Category</div>
            <div class="value">{{ doc.get("custom_po_category") or "-" }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">Type</div>
            <div class="value">{{ doc.get("custom_po_type") or "-" }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">Dept</div>
            <div class="value">{{ doc.get("custom_po_department") or "-" }}</div>
        </div>
        {% if supplier_doc and supplier_doc.get("mobile_no") %}
        <div class="meta-cell">
            <div class="label">Contact</div>
            <div class="value">{{ supplier_doc.mobile_no }}</div>
        </div>
        {% endif %}
        <div class="meta-cell">
            <div class="label">Schedule Date</div>
            <div class="value">{{ frappe.utils.formatdate(doc.schedule_date, "dd-MM-yyyy") if doc.schedule_date else "-" }}</div>
        </div>
        <div class="meta-cell">
            <div class="label">Zero Qty</div>
            <div class="value">{{ doc.get("custom_zero_qty") or "No" }}</div>
        </div>
    </div>

    <!-- Items Table -->
    <table class="items-table">
        <thead>
            <tr>
                <th style="width:25px;">S.No</th>
                <th class="text-left">Alias</th>
                <th class="text-left">Item Name</th>
                {% if show_stock %}<th>Stock in Hand</th>{% endif %}
                {% if show_transit %}<th>Transit Stock</th>{% endif %}
                {% if show_packing %}
                <th>Req. (Loose)</th>
                <th>Req. Pack(s)</th>
                {% endif %}
                <th class="text-right">Purchase Price</th>
                {% if show_discount %}<th class="text-right">Disc (%)</th>{% endif %}
                <th class="text-right">Amount</th>
                {% if show_generic %}<th class="text-left">Generic Item</th>{% endif %}
                {% if show_category %}
                <th class="text-left">Category</th>
                <th class="text-left">Class</th>
                {% endif %}
                {% if show_packing %}
                <th>Item Packing</th>
                <th class="text-right">Pack Units</th>
                {% endif %}
                <th class="text-right">Qty</th>
            </tr>
        </thead>
        <tbody>
            {% for item in doc.items %}
            <tr>
                <td class="text-center">{{ loop.index }}</td>
                <td class="text-left">{{ item.get("custom_alias") or "" }}</td>
                <td class="text-left fw-bold">{{ item.item_name }}</td>
                {% if show_stock %}<td class="text-right">{{ item.get("custom_stock_in_hand") or 0 }}</td>{% endif %}
                {% if show_transit %}<td class="text-right">{{ item.get("custom_transit_stock") or 0 }}</td>{% endif %}
                {% if show_packing %}
                <td class="text-right">{{ item.get("custom_required_loose") or 0 }}</td>
                <td class="text-right">{{ item.get("custom_required_packs") or 0 }}</td>
                {% endif %}
                <td class="text-right">{{ frappe.utils.fmt_money(item.rate, currency=currency) }}</td>
                {% if show_discount %}<td class="text-right">{{ item.discount_percentage or 0 }}%</td>{% endif %}
                <td class="text-right fw-bold">{{ frappe.utils.fmt_money(item.amount, currency=currency) }}</td>
                {% if show_generic %}<td class="text-left">{{ item.get("custom_generic_item") or "" }}</td>{% endif %}
                {% if show_category %}
                <td class="text-left">{{ item.get("custom_category") or "" }}</td>
                <td class="text-left">{{ item.get("custom_class") or "" }}</td>
                {% endif %}
                {% if show_packing %}
                <td class="text-center">{{ item.get("custom_item_packing") or "" }}</td>
                <td class="text-right">{{ item.get("custom_pack_units") or "" }}</td>
                {% endif %}
                <td class="text-right fw-bold">{{ item.qty }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Totals -->
    <div class="totals-block">
        <table class="totals-table">
            <tr>
                <td>Total Items</td>
                <td>{{ doc.items | length }}</td>
            </tr>
            <tr>
                <td>Total Qty</td>
                <td>{{ doc.total_qty or 0 }}</td>
            </tr>
            <tr>
                <td>Subtotal</td>
                <td>{{ frappe.utils.fmt_money(doc.total or doc.net_total, currency=currency) }}</td>
            </tr>
            {% if doc.discount_amount and doc.discount_amount > 0 %}
            <tr>
                <td>Inv. Disc ({{ doc.additional_discount_percentage or 0 }}%)</td>
                <td>-{{ frappe.utils.fmt_money(doc.discount_amount, currency=currency) }}</td>
            </tr>
            {% endif %}
            {% for tax in doc.taxes %}
            <tr>
                <td>{{ tax.description or "Tax" }} {% if tax.rate %}({{ tax.rate }}%){% endif %}</td>
                <td>{{ frappe.utils.fmt_money(tax.tax_amount, currency=currency) }}</td>
            </tr>
            {% endfor %}
            <tr class="grand-total">
                <td>Grand Total</td>
                <td>{{ frappe.utils.fmt_money(doc.rounded_total or doc.grand_total, currency=currency) }}</td>
            </tr>
        </table>
    </div>

    <!-- Remarks -->
    {% if doc.get("custom_po_remarks") %}
    <div class="remarks-section">
        <div class="label">Remarks</div>
        <div>{{ doc.custom_po_remarks }}</div>
    </div>
    {% endif %}

    <!-- Signature -->
    <div class="po-footer">
        <div class="signature-block">
            <div class="signature-line">Prepared By</div>
        </div>
        <div class="signature-block">
            <div class="signature-line">Authorized Signature</div>
        </div>
        <div class="signature-block">
            <div class="signature-line">Supplier Signature</div>
        </div>
    </div>

    <div class="po-print-footer">
        Powered by XPOS &bull; {{ frappe.utils.formatdate(frappe.utils.nowdate(), "yyyy") }}
    </div>
</div>
